"""### Métricas ARIMAX"""

# Calcular residuos
resid_2 = y - df_reg['ARIMAX_2']
resid_3 = y - df_reg['ARIMAX_3']
resid_4 = y - df_reg['ARIMAX_4']

# Durbin-Watson
dw_2 = durbin_watson(resid_2)
dw_3 = durbin_watson(resid_3)
dw_4 = durbin_watson(resid_4)

# Función de métricas adicionales
def calcular_metricas(y_true, y_pred):
    mae = np.mean(np.abs(y_true - y_pred))
    mape = np.mean(np.abs((y_true - y_pred) / y_true)) * 100
    r2_pseudo = 1 - np.var(y_true - y_pred) / np.var(y_true)
    return mae, mape, r2_pseudo

# Métricas
mae_2, mape_2, r2_2 = calcular_metricas(y, df_reg['ARIMAX_2'])
mae_3, mape_3, r2_3 = calcular_metricas(y, df_reg['ARIMAX_3'])
mae_4, mape_4, r2_4 = calcular_metricas(y, df_reg['ARIMAX_4'])

# Crear tabla
