"""## Crear DataFrame

Los escenarios se construyen sobre proyecciones realistas basadas en tendencias estructurales observadas y literatura demográfica.

Aquí se incorpora:

* Envejecimiento sostenido

* Desaceleración del crecimiento migratorio

* Tendencia decreciente del crecimiento vegetativo

* Dinámica macroeconómica no lineal en el PIB
"""

# Años futuros
futuro = list(range(2025, 2051))
n_years = len(futuro)

# Último año observado
last_row = df_reg[df_reg['Año'] == 2024].iloc[0]

# Variables base
last_65 = last_row['Población_mayores_65']
last_veg = last_row['Crecimiento_vegetativo']
last_mig = last_row['Stock_extranjeros']
last_pib = last_row['PIB_per_capita']

# Parámetros proyectivos por escenario
tasa_65 = {'pes': 1.020, 'neu': 1.015, 'opt': 1.010}  # crecimiento compuesto
decaimiento_veg = {'pes': 1.05, 'neu': 1.03, 'opt': 1.01}  # vegetativo más negativo
tasa_mig = {'pes': 0.98, 'neu': 1.002, 'opt': 1.010}  # suavizado de neutral
tasa_pib_ciclo = {
    'pes': [0.5, 1.0, 1.0, 0.0, -1.0],     # incluye shock recesivo
    'neu': [1.2, 1.5, 1.0, 1.8, 1.5],
    'opt': [2.0, 2.5, 2.2, 2.5, 2.0]
}

# Migración neta base
delta_mig_base = df_reg['Stock_extranjeros'].diff().rolling(5).mean().iloc[-1]
np.random.seed(42)

# Crear DataFrame
df_escenarios = pd.DataFrame()

for esc in ['pes', 'neu', 'opt']:
    temp = pd.DataFrame()
    temp['Año'] = futuro
    temp['Escenario'] = esc

    # Población mayores de 65
    temp['Población_mayores_65'] = [last_65 * (tasa_65[esc] ** i) for i in range(1, n_years + 1)]

    # Crecimiento vegetativo decreciente
    temp['Crecimiento_vegetativo'] = [last_veg / (decaimiento_veg[esc] ** i) for i in range(1, n_years + 1)]

    # Migración con variabilidad y tasas diferenciadas
    variacion_mig = delta_mig_base * (tasa_mig[esc] ** np.arange(1, n_years + 1))
    ruido = np.random.normal(loc=0, scale=0.05, size=n_years)
    variacion_mig *= (1 + ruido)
    temp['Stock_extranjeros'] = last_mig + np.cumsum(variacion_mig)

    # PIB per cápita con ciclo y shock
    ciclo = tasa_pib_ciclo[esc] * (n_years // 5) + tasa_pib_ciclo[esc][:n_years % 5]
    pib_projection = [last_pib]
    for i in ciclo:
        nuevo_valor = pib_projection[-1] * (1 + i / 100)
        pib_projection.append(nuevo_valor)
    temp['PIB_per_capita'] = pib_projection[1:]

    df_escenarios = pd.concat([df_escenarios, temp], ignore_index=True)

