"""## Evolución de la Tasa de Cobertura del Sistema de Pensiones (Afiliados / Pensionistas)"""

# ==========================
# Preparación de datos
# ==========================

# Convertir la columna 'Fecha' a datetime
df_pensiones['Fecha'] = pd.to_datetime(df_pensiones['Fecha'], format='%m/%Y')

# Orden cronológico
df_pensiones = df_pensiones.sort_values('Fecha')

# Crear columna de Tasa de Cobertura
df_pensiones['Tasa_cobertura'] = df_pensiones['Afiliados'] / df_pensiones['Pensionistas']

# ==========================
# Visualización temporal
# ==========================

