# ==========================
# Estadísticos descriptivos
# ==========================

print("Resumen estadístico de la Tasa de Cobertura (Afiliados / Pensionistas):\n")
print(df_pensiones['Tasa_cobertura'].describe())

# Opcional: tasa media anual para informes
cobertura_anual = df_pensiones.set_index('Fecha')['Tasa_cobertura'].resample('Y').mean()

"""## Interpolación de los valores anuales de afiliados"""

# Copia para interpolación
df_interp = df_pensiones.copy()

# Paso 1: marcar como NaN todos los afiliados excepto los de enero de cada año o después de 2023
df_interp['Mes'] = df_interp['Fecha'].dt.month
df_interp['Año'] = df_interp['Fecha'].dt.year

# Condición: mantener afiliados solo en enero o si el año es 2023 o posterior
cond_real = (df_interp['Mes'] == 1) | (df_interp['Año'] >= 2023)
df_interp.loc[~cond_real, 'Afiliados'] = np.nan

# Paso 2: interpolar los afiliados de forma lineal mes a mes
df_interp['Afiliados_interp'] = df_interp['Afiliados'].interpolate(method='linear')

# Paso 3: nueva tasa de cobertura interpolada
df_interp['Tasa_cobertura_interp'] = df_interp['Afiliados_interp'] / df_interp['Pensionistas']

# Paso 4: graficar comparación
plt.figure(figsize=(12, 6))
