"""## Predicciones

### Sin Anclaje
"""

# 1) Preparar y re-ajustar el modelo ARIMAX con datos hasta 2024
# --------------------------
exog_cols = ['Población_mayores_65', 'Crecimiento_vegetativo', 'Stock_extranjeros', 'PIB_per_capita']

model_future = SARIMAX(
    endog=df_reg['Tasa_dependencia'],
    exog=df_reg[exog_cols],
    order=order_4,  # mismo (p,d,q) que seleccionaste (p=1,d=1,q=0)
    enforce_stationarity=False,
    enforce_invertibility=False
).fit(disp=False)

# --------------------------
# 2) Construir proyecciones Real vs. Contrafactual por escenario
# --------------------------
dfs_out = []

for esc in ['pes','neu','opt']:
    # a) Exógenas "reales" (tal como las definiste en df_escenarios)
    df_esc = df_escenarios[df_escenarios['Escenario']==esc].copy()
    exog_future_real = df_esc[exog_cols].copy()

    # b) Exógenas contrafactuales: Stock_extranjeros=0
    exog_future_cf = exog_future_real.copy()
    exog_future_cf['Stock_extranjeros'] = 0.0

    # c) Predicciones de tasa de dependencia (2025–2050)
    #    - "Real": podemos usar df_pred si ya lo tienes, o recomputar para consistencia
    fc_real = model_future.predict(
        start=len(df_reg),
        end=len(df_reg)+len(exog_future_real)-1,
        exog=exog_future_real
    )

    fc_cf = model_future.predict(
        start=len(df_reg),
        end=len(df_reg)+len(exog_future_cf)-1,
        exog=exog_future_cf
    )

    # d) Combinar en un DataFrame
    tmp = df_esc[['Año','Escenario']].copy()
    tmp['Tasa_dependencia_real_proj'] = np.array(fc_real)
    tmp['Tasa_dependencia_cf_proj']  = np.array(fc_cf)

    # e) Cobertura "real": ya la tienes en df_sim
    sim_real = df_sim[df_sim['Escenario']==esc][['Año','Tasa_cobertura_sim']].rename(
        columns={'Tasa_cobertura_sim':'Tasa_cobertura_real_proj'}
    )

    # f) Cobertura contrafactual:
    #    - PEA contrafactual = PEA proyectada - Stock_extranjeros (siempre >=0)
    #    - Afiliados_cf = 0.85 * PEA_cf (mismo multiplicador de tu notebook)
    #    - Pensionistas = 0.9 * Población_mayores_65 (misma definición)
    #    NOTA: usamos la PEA proyectada ya calculada en df_pred
    pea_proj = df_pred[df_pred['Escenario']==esc][['Año','Población_edad_trabajar_proj']].copy()
    pea_proj = pea_proj.sort_values('Año')

    # Alinear pesos con df_esc ordenado por año
    df_esc_sorted = df_esc.sort_values('Año').reset_index(drop=True)
    pea_proj_sorted = pea_proj.sort_values('Año').reset_index(drop=True)

    # PEA contrafactual restando el stock extranjero REAL del escenario (eliminado en el contrafactual)
    pea_cf = (pea_proj_sorted['Población_edad_trabajar_proj'] - df_esc_sorted['Stock_extranjeros']).clip(lower=0)

    afiliados_cf = 0.85 * pea_cf
    pensionistas = 0.9 * df_esc_sorted['Población_mayores_65']
    tasa_cob_cf = afiliados_cf / pensionistas

    sim_cf = pd.DataFrame({
        'Año': df_esc_sorted['Año'],
        'Tasa_cobertura_cf_proj': tasa_cob_cf
    })

    # g) Unir coberturas
    tmp = tmp.merge(sim_real, on='Año', how='left').merge(sim_cf, on='Año', how='left')

    # h) IPD proyectado: real vs. contrafactual
    tmp['IPD_real_proj'] = tmp['Tasa_dependencia_real_proj'] / tmp['Tasa_cobertura_real_proj']
    tmp['IPD_cf_proj']   = tmp['Tasa_dependencia_cf_proj']  / tmp['Tasa_cobertura_cf_proj']

    dfs_out.append(tmp)

df_proj_comp = pd.concat(dfs_out, ignore_index=True)

# --------------------------
# 3) Gráficos comparativos 2025–2050 (por escenario)
# --------------------------
def plot_compare_future(df_proj_comp, escenario):
    dat = df_proj_comp[df_proj_comp['Escenario']==escenario].sort_values('Año')

    # Dependencia
    plt.figure(figsize=(10,5))
    plt.plot(dat['Año'], dat['Tasa_dependencia_real_proj'], label='Con Migración', lw=2)
    plt.plot(dat['Año'], dat['Tasa_dependencia_cf_proj'],   label='Sin migración', lw=2, linestyle='--')
    plt.title(f"Tasa de dependencia (2025–2050) – Escenario {escenario}")
    plt.xlabel("Año"); plt.ylabel("Tasa de dependencia (%)")
    plt.grid(True); plt.legend(); plt.tight_layout(); plt.show()

    # Cobertura
    plt.figure(figsize=(10,5))
    plt.plot(dat['Año'], dat['Tasa_cobertura_real_proj'], label='Con Migración', lw=2)
    plt.plot(dat['Año'], dat['Tasa_cobertura_cf_proj'],   label='Sin migración', lw=2, linestyle='--')
    plt.title(f"Tasa de cobertura (2025–2050) – Escenario {escenario}")
    plt.xlabel("Año"); plt.ylabel("Afiliados por pensionista")
    plt.grid(True); plt.legend(); plt.tight_layout(); plt.show()

    # IPD
    plt.figure(figsize=(10,5))
    plt.plot(dat['Año'], dat['IPD_real_proj'], label='Con Migración', lw=2)
    plt.plot(dat['Año'], dat['IPD_cf_proj'],   label='Sin migración', lw=2, linestyle='--')
    plt.title(f"Índice de Presión Demográfica (2025–2050) – Escenario {escenario}")
    plt.xlabel("Año"); plt.ylabel("IPD = Dependencia / Cobertura")
    plt.grid(True); plt.legend(); plt.tight_layout(); plt.show()

# Ejecuta para cada escenario:
for esc in ['pes','neu','opt']:
    plot_compare_future(df_proj_comp, esc)

COLORS = {'pes': 'tab:red', 'neu': 'tab:blue', 'opt': 'tab:green'}

def plot_hist_and_future(
    df_hist_real,          # DataFrame con ['Año','y_real_hist']
    df_hist_cf,            # DataFrame con ['Año','y_cf_hist'] (contrafactual histórico)
    df_proj_comp,          # DataFrame con proyecciones y 'Escenario'
    y_real_col_proj,       # nombre col. con-migración en proyección
    y_cf_col_proj,         # nombre col. sin-migración en proyección
    title, ylabel,
    hist_last_year=2023    # último año que se dibuja como "histórico" (ej. 2023)
):
    # ------------- Tramo histórico -------------
    # Histórico REAL (línea continua)
    hist_real = df_hist_real[df_hist_real['Año'] <= hist_last_year]
    plt.figure(figsize=(11,6))
    ax = plt.gca()
    ax.plot(hist_real['Año'], hist_real['y_real_hist'], label='Histórico (real)', linewidth=2)

    # Histórico SIN migración (línea discontinua)
    hist_cf = df_hist_cf[df_hist_cf['Año'] <= hist_last_year]
    if not hist_cf.empty:
        ax.plot(hist_cf['Año'], hist_cf['y_cf_hist'], label='Histórico (sin migración)', linewidth=2, linestyle='--')

    # Línea vertical separadora (histórico vs proyección)
    ax.axvline(hist_last_year + 0.5, color='gray', linestyle=':', linewidth=1)

    # ------------- Tramo futuro 2025–2050 -------------
    for esc in ['pes', 'neu', 'opt']:
        sub = df_proj_comp[df_proj_comp['Escenario'] == esc].copy()
        # Nos quedamos solo con años > hist_last_year
        sub = sub[sub['Año'] > hist_last_year]

        if sub.empty:
            continue  # si no hay filas, no trazamos

        # Con migración: línea continua
        ax.plot(
            sub['Año'], sub[y_real_col_proj],
            label=f"{esc.upper()} (con migración)",
            color=COLORS[esc], linewidth=2
        )
        # Sin migración: línea discontinua
        ax.plot(
            sub['Año'], sub[y_cf_col_proj],
            label=f"{esc.upper()} (sin migración)",
            color=COLORS[esc], linewidth=2, linestyle='--'
        )

    # Estética
    ax.set_title(title)
    ax.set_xlabel("Año")
    ax.set_ylabel(ylabel)
    ax.grid(True, alpha=0.3)
    ax.legend(ncol=2)
    plt.tight_layout()
    plt.show()

