"""### Con Anclaje"""

# ===== Configuración =====
HIST_LAST_YEAR = 2023      # último año histórico que dibujas
ANCHOR_YEAR    = 2024      # año al que queremos anclar por continuidad (si no existe, se extrapola)

ESCENARIOS = ['pes','neu','opt']  # orden esperado en df_proj_comp

def _extrapolate_anchor_2024(df_hist_cf, value_col='y_cf_hist', hist_last_year=HIST_LAST_YEAR, anchor_year=ANCHOR_YEAR):
    """
    Devuelve el valor contrafactual para 'anchor_year' (ej. 2024).
    Si existe en df_hist_cf, lo usa; si no, extrapola linealmente desde los dos últimos años <= hist_last_year.
    Si solo hay un año, usa ese mismo valor.
    """
    dfh = df_hist_cf[['Año', value_col]].dropna().sort_values('Año').copy()

    # 1) Si ya tenemos el año ancla en histórico, úsalo.
    row = dfh[dfh['Año'] == anchor_year]
    if not row.empty:
        return float(row[value_col].iloc[0])

    # 2) Si no, usa los dos últimos puntos <= hist_last_year para extrapolar
    dfh_cut = dfh[dfh['Año'] <= hist_last_year]
    if len(dfh_cut) >= 2:
        y2, a2 = float(dfh_cut[value_col].iloc[-1]), int(dfh_cut['Año'].iloc[-1])
        y1, a1 = float(dfh_cut[value_col].iloc[-2]), int(dfh_cut['Año'].iloc[-2])
        slope = (y2 - y1) / (a2 - a1) if (a2 - a1) != 0 else 0.0
        return y2 + slope * (anchor_year - a2)
    else:
        # 3) Con un solo dato, usa ese mismo valor
        return float(dfh_cut[value_col].iloc[-1])

def _anchor_projection_cf(
        df_proj_comp, df_hist_cf, proj_col,
        hist_last_year=HIST_LAST_YEAR, anchor_year=ANCHOR_YEAR,
        lower_clip=None
    ):
    """
    Ancla la columna de proyección 'proj_col' (sin migración) para que el primer año > hist_last_year
    coincida con el valor contrafactual estimado para 'anchor_year' (continuidad).
    Aplica el ajuste de forma aditiva (shift) y opcionalmente limita inferiormente (clip).
    """
    # Estimar valor ancla contrafactual (p.ej. 2024)
    anchor_val = _extrapolate_anchor_2024(df_hist_cf, value_col='y_cf_hist',
                                          hist_last_year=hist_last_year, anchor_year=anchor_year)

    # Ajustar por escenario
    for esc in ESCENARIOS:
        mask_esc  = (df_proj_comp['Escenario'] == esc)
        sub       = df_proj_comp[mask_esc]
        # Primer año futuro
        future    = sub[sub['Año'] > hist_last_year]
        if future.empty:
            continue
        first_year = int(future['Año'].min())

        # Diferencia (shift) necesaria para continuidad
        current_start = float(df_proj_comp.loc[mask_esc & (df_proj_comp['Año'] == first_year), proj_col].iloc[0])
        shift = anchor_val - current_start

        # Aplicar shift desde el primer año futuro en adelante
        mask_future = mask_esc & (df_proj_comp['Año'] >= first_year)
        df_proj_comp.loc[mask_future, proj_col] = df_proj_comp.loc[mask_future, proj_col] + shift

        # Clip si procede (para evitar negativos o ratios ilógicos)
        if lower_clip is not None:
            df_proj_comp.loc[mask_future, proj_col] = df_proj_comp.loc[mask_future, proj_col].clip(lower=lower_clip)

    return df_proj_comp

# Histórico CONTRAFACTUAL por métrica (coinciden con lo que ya trazas en los gráficos)
hist_dep_cf = df_comp[['Año','Tasa_dependencia_sin_mig']].rename(columns={'Tasa_dependencia_sin_mig':'y_cf_hist'})
hist_cov_cf = df_comp[['Año','Tasa_cobertura_sin_mig']].rename(columns={'Tasa_cobertura_sin_mig':'y_cf_hist'})
# El IPD contrafactual lo recalcularemos tras anclar dependencia y cobertura,
# pero también podemos inspeccionarlo si lo necesitas:
hist_ipd_cf = df_comp[['Año','IPD_sin_mig']].rename(columns={'IPD_sin_mig':'y_cf_hist'})

# Dependencia (sin migración)
df_proj_comp = _anchor_projection_cf(
    df_proj_comp=df_proj_comp,
    df_hist_cf=hist_dep_cf,
    proj_col='Tasa_dependencia_cf_proj',
    hist_last_year=HIST_LAST_YEAR,
    anchor_year=ANCHOR_YEAR,
    lower_clip=0.0
)

# Cobertura (sin migración)
df_proj_comp = _anchor_projection_cf(
    df_proj_comp=df_proj_comp,
    df_hist_cf=hist_cov_cf,
    proj_col='Tasa_cobertura_cf_proj',
    hist_last_year=HIST_LAST_YEAR,
    anchor_year=ANCHOR_YEAR,
    lower_clip=0.01
)

# Recalcular IPD contrafactual proyectado con las series corregidas
df_proj_comp['IPD_cf_proj'] = (
    df_proj_comp['Tasa_dependencia_cf_proj'] / df_proj_comp['Tasa_cobertura_cf_proj']
)

def _peek_continuity(df_proj_comp, df_hist_cf, proj_col, label):
    anchor_val = _extrapolate_anchor_2024(df_hist_cf, 'y_cf_hist', HIST_LAST_YEAR, ANCHOR_YEAR)
    for esc in ESCENARIOS:
        first_year = int(df_proj_comp[(df_proj_comp['Escenario']==esc) & (df_proj_comp['Año']>HIST_LAST_YEAR)]['Año'].min())
        start_val  = float(df_proj_comp[(df_proj_comp['Escenario']==esc) & (df_proj_comp['Año']==first_year)][proj_col].iloc[0])
        print(f"{label} | {esc.upper()} | ancla( {ANCHOR_YEAR} )={anchor_val:.3f}  ->  proyección({first_year})={start_val:.3f}  Δ={start_val-anchor_val:+.3f}")

_peek_continuity(df_proj_comp, hist_dep_cf, 'Tasa_dependencia_cf_proj', "Dependencia CF")
_peek_continuity(df_proj_comp, hist_cov_cf, 'Tasa_cobertura_cf_proj',   "Cobertura CF")

# --- DEPENDENCIA ---
plot_hist_and_future(
    df_hist_real=hist_dep_real,
    df_hist_cf=hist_dep_cf,
    df_proj_comp=df_proj_comp,
    y_real_col_proj='Tasa_dependencia_real_proj',
    y_cf_col_proj='Tasa_dependencia_cf_proj',
    title="Tasa de dependencia: histórico (real y sin migración) y proyecciones por escenario",
    ylabel="Tasa de dependencia (%)",
    hist_last_year=2023
)

# --- COBERTURA ---
plot_hist_and_future(
    df_hist_real=hist_cov_real,
    df_hist_cf=hist_cov_cf,
    df_proj_comp=df_proj_comp,
    y_real_col_proj='Tasa_cobertura_real_proj',
    y_cf_col_proj='Tasa_cobertura_cf_proj',
    title="Tasa de cobertura: histórico (real y sin migración) y proyecciones por escenario",
    ylabel="Afiliados por pensionista",
    hist_last_year=2023
)

# --- IPD ---
plot_hist_and_future(
    df_hist_real=hist_ipd_real,
    df_hist_cf=hist_ipd_cf,
    df_proj_comp=df_proj_comp,
    y_real_col_proj='IPD_real_proj',
    y_cf_col_proj='IPD_cf_proj',
    title="Índice de Presión Demográfica (IPD): histórico (real y sin migración) y proyecciones por escenario",
    ylabel="IPD = Dependencia / Cobertura",
    hist_last_year=2023
)

