# === CONTRAFACTUAL (robusto al nombre de la columna) ===
import numpy as np
from tfm_exporter import export_contrafactual

PATH_XLSX = PATH_XLSX  # ya definido antes
anos_clave = [2025, 2035, 2050]

# 1) Detectar la columna de dependencia en df_pred (según tu flujo puede ser 'Tasa_dependencia' o 'Tasa_dependencia_pred')
dep_col = "Tasa_dependencia" if "Tasa_dependencia" in df_pred.columns else "Tasa_dependencia_pred"

# 2) Tomar de df_pred las columnas demográficas + dependencia
cols_pred = [
    "Año", "Escenario", dep_col,
    "Población_edad_trabajar_proj",
    "Población_mayores_65",
    "Stock_extranjeros",
]
faltan = [c for c in cols_pred if c not in df_pred.columns]
if faltan:
    raise KeyError(f"Faltan columnas en df_pred: {faltan}")

base = df_pred[cols_pred].copy().rename(columns={dep_col: "Tasa_dependencia"})

# 3) Añadir SOLO la cobertura simulada desde df_sim
if "Tasa_cobertura_sim" not in df_sim.columns:
    raise KeyError("df_sim no tiene 'Tasa_cobertura_sim'. Ejecuta antes la celda que la calcula.")

base = base.merge(
    df_sim[["Año", "Escenario", "Tasa_cobertura_sim"]],
    on=["Año", "Escenario"], how="inner"
)

# 4) Cobertura sin migración (quitamos aportación del Stock de extranjeros a afiliados)
base["Afiliados_sin_mig"] = 0.85 * base["Población_edad_trabajar_proj"]
base["Pensionistas_est"]  = 0.90 * base["Población_mayores_65"]
base["Cobertura_sin_mig"] = base["Afiliados_sin_mig"] / base["Pensionistas_est"]

# 5) IPD con y sin migración (dependencia como fracción)
dep = base["Tasa_dependencia"]
dep_frac = dep/100.0 if dep.max() > 1 else dep

sel = base["Año"].isin(anos_clave)
df_cf = base.loc[sel, ["Escenario", "Año"]].copy()
df_cf["IPD con migración"] = dep_frac.loc[sel].values / base.loc[sel, "Tasa_cobertura_sim"].values
df_cf["IPD sin migración"] = dep_frac.loc[sel].values / base.loc[sel, "Cobertura_sin_mig"].values

# 6) Exportar hoja 6_Contrafactual
