    fc = res.get_forecast(steps=len(g_future), exog=X_future)
    mean_dep = pd.Series(fc.predicted_mean.values, index=idx_future)
    ci = fc.conf_int(alpha=0.20)  # 80% (ajusta a 0.05 si quieres 95%)
    dep_low = pd.Series(ci.iloc[:,0].values, index=idx_future)
    dep_up  = pd.Series(ci.iloc[:,1].values, index=idx_future)

