# Cálculo de CAGR por escenario y variable (2025-2050)
def _cagr(s):
    s = s.dropna()
    if len(s) < 2 or s.iloc[0] == 0:
        return np.nan
    return (s.iloc[-1] / s.iloc[0]) ** (1 / (len(s)-1)) - 1

