    esc_rows.append({
        "Escenario": esc,
        "GE65_CAGR": _cagr(g2050["Población_mayores_65"]),
        "VEG_CAGR": _cagr(g2050["Crecimiento_vegetativo"].abs()),  # si es neto, puedes dejar sin abs
        "STOCK_EXT_CAGR": _cagr(g2050["Stock_extranjeros"]),
        "PIB_PC_CAGR": _cagr(g2050["PIB_per_capita"])
    })
