# ==== Requiere: pandas as pd, numpy as np, matplotlib.pyplot as plt, statsmodels.api as sm
from statsmodels.tsa.statespace.sarimax import SARIMAX

# ---------- 0) Helpers ----------
def to_frac(series):
    """Detecta si viene en % (>1) y convierte a fracción."""
    s = series.astype(float)
    return s/100.0 if s.mean() > 1 else s

def to_pct(series):
    """Convierte fracción a % para graficar."""
    s = series.astype(float)
    return s*100 if s.max() <= 1.5 else s

# ---------- 1) Preparar histórico ----------
# Columnas mínimas esperadas en df_reg: Año, Tasa_dependencia, Población_total, Población_edad_trabajar,
# Población_mayores_65, Stock_extranjeros
dep_hist_frac = to_frac(df_reg['Tasa_dependencia']).copy()

# Dependencia "sin migración" histórica (ilustrativa B): restar extranjeros de la población en edad de trabajar
if 'Población_total' in df_reg.columns and 'Población_edad_trabajar' in df_reg.columns:
    pet_sin_mig_hist = (df_reg['Población_edad_trabajar'] - df_reg['Stock_extranjeros']).clip(lower=1)
    dep_sin_mig_hist_frac = ((df_reg['Población_total'] - pet_sin_mig_hist) / pet_sin_mig_hist)
else:
    # Si faltan columnas, igualamos a la real para no romper el gráfico
    dep_sin_mig_hist_frac = dep_hist_frac.copy()

# ---------- 2) Ajustar ARIMAX M2 (1,1,0) ----------
exog_cols_m2 = ['Población_mayores_65','Stock_extranjeros']
model_m2 = SARIMAX(dep_hist_frac, exog=df_reg[exog_cols_m2],
                   order=(1,1,0), enforce_stationarity=False, enforce_invertibility=False).fit(disp=False)

# ---------- 3) Escenarios futuros 2025–2050 ----------
# df_escenarios: Año, Escenario, Población_mayores_65, Stock_extranjeros  (y opcional Población_edad_trabajar_proj)
esc_order = ['pes','neu','opt']

# Si no existe proyección de población en edad de trabajar, la generamos suave por escenario (puedes ajustar tasas):
if 'Población_edad_trabajar_proj' not in df_escenarios.columns:
    last_pet = df_reg.loc[df_reg['Año']==df_reg['Año'].max(),'Población_edad_trabajar'].iloc[0]
    tasas_pet = {'pes':0.999, 'neu':1.000, 'opt':1.002}  # suaves y conservadoras
    pet_proj = []
    for esc in esc_order:
        tmp = df_escenarios[df_escenarios['Escenario']==esc].copy()
        g = tasas_pet[esc]
        años = tmp['Año'].sort_values().values
        serie = [last_pet*(g**i) for i in range(1, len(años)+1)]
        tmp['Población_edad_trabajar_proj'] = serie
        pet_proj.append(tmp)
    df_escenarios = pd.concat(pet_proj, ignore_index=True)

# ---------- 4) Proyección de dependencia con M2 (con y sin migración en exógenas) + ANCLAJE DOBLE ----------
ANCLAR_2024 = True
# último observado (real) y último "histórico sin migración" en fracción
ult_dep_real_2024 = float(to_frac(df_reg['Tasa_dependencia']).iloc[-1])
ult_dep_sin_2024  = float(dep_sin_mig_hist_frac.iloc[-1])  # construido antes en el script

pred_list, pred_list_no_mig = [], []
for esc in esc_order:
    df_esc = df_escenarios[df_escenarios['Escenario']==esc].copy()
    exog_fut = df_esc[exog_cols_m2]

    # 4.1 con migración (exógenas tal cual)
    fc_con = model_m2.get_forecast(steps=len(df_esc), exog=exog_fut).predicted_mean

    # 4.2 sin migración total (ilustrativo): anular stock extranjeros en exógenas
    exog0 = exog_fut.copy()
    exog0['Stock_extranjeros'] = 0
    fc_sin = model_m2.get_forecast(steps=len(df_esc), exog=exog0).predicted_mean

    if ANCLAR_2024:
        # ancla con migración al último real 2024
        fc_con = fc_con - fc_con.iloc[0] + ult_dep_real_2024
        # ancla sin migración al último "histórico sin migración" 2024
        fc_sin = fc_sin - fc_sin.iloc[0] + ult_dep_sin_2024

    out_con = df_esc[['Año','Escenario']].copy()
    out_con['Dep_frac_con_mig'] = fc_con.values
    pred_list.append(out_con)

    out_sin = df_esc[['Año','Escenario']].copy()
    out_sin['Dep_frac_sin_mig'] = fc_sin.values
    pred_list_no_mig.append(out_sin)

dep_fut  = pd.concat(pred_list, ignore_index=True)
dep_fut0 = pd.concat(pred_list_no_mig, ignore_index=True)


# ---------- 5) Cobertura simulada por escenario (regla calibrada) ----------
def cobertura_sim(dfE, apagar_migracion=False, ajustar_pet_por_migracion=False):
    out = []
    for esc in esc_order:
        tmp = dfE[dfE['Escenario']==esc].copy()
        pet = tmp['Población_edad_trabajar_proj'].copy()
        stock = tmp['Stock_extranjeros'].copy()
        if ajustar_pet_por_migracion:  # para el contrafactual ilustrativo B
            pet = (pet - stock).clip(lower=1)
        # afiliados y pensionistas
        afiliados = 0.85*pet + (0.0 if apagar_migracion else 0.25*stock)
        pensionistas = 0.90*tmp['Población_mayores_65']
        tmp['Cobertura'] = afiliados / pensionistas
        out.append(tmp[['Año','Escenario','Cobertura']])
    return pd.concat(out, ignore_index=True)

# A) principal (canal cobertura): sin migración = solo apagar el término migratorio en la cobertura
cov_fut_con = cobertura_sim(df_escenarios, apagar_migracion=False, ajustar_pet_por_migracion=False)
cov_fut_sin_cov = cobertura_sim(df_escenarios, apagar_migracion=True, ajustar_pet_por_migracion=False)

# B) ilustrativo (sin migración total): además restar extranjeros de la población en edad laboral
cov_fut_sin_total = cobertura_sim(df_escenarios, apagar_migracion=True, ajustar_pet_por_migracion=True)

# ---------- 6) Figuras (3 paneles) ----------

# 6.1 Dependencia (%): histórico (real y sin migración) + proyecciones con/sin migración
plt.figure(figsize=(12,6))
plt.plot(df_reg['Año'], to_pct(dep_hist_frac), label='Histórico (real)', color='tab:blue')
plt.plot(df_reg['Año'], to_pct(dep_sin_mig_hist_frac), '--', label='Histórico (sin migración)', color='tab:orange')

for esc, col in zip(esc_order, ['tab:red','tab:blue','tab:green']):
    d1 = dep_fut[dep_fut['Escenario']==esc]
    d0 = dep_fut0[dep_fut0['Escenario']==esc]
    plt.plot(d1['Año'], to_pct(d1['Dep_frac_con_mig']), color=col, label=f'{esc.upper()} (con migración)')
    plt.plot(d0['Año'], to_pct(d0['Dep_frac_sin_mig']), color=col, linestyle='--', label=f'{esc.upper()} (sin migración)')

plt.title('Tasa de dependencia: histórico (real/sin migración) y proyecciones por escenario')
plt.xlabel('Año'); plt.ylabel('Tasa de dependencia (%)'); plt.grid(True); plt.legend(ncol=2); plt.tight_layout(); plt.show()

# 6.2 Cobertura: histórico (real vs. contrafactual cobertura) y proyecciones con/sin migración
# Histórico de cobertura con la misma regla (si tienes serie oficial, puedes superponerla aparte)
af_real = 0.85*df_reg['Población_edad_trabajar'] + 0.25*df_reg['Stock_extranjeros']
pens_real = 0.90*df_reg['Población_mayores_65']
cov_hist = af_real / pens_real

af_sin = 0.85*(df_reg['Población_edad_trabajar'])  # canal cobertura: no restamos stock del PET histórico
cov_hist_sin = af_sin / pens_real

plt.figure(figsize=(12,6))
plt.plot(df_reg['Año'], cov_hist, label='Histórico (regla calibrada)', color='tab:blue')
plt.plot(df_reg['Año'], cov_hist_sin, '--', label='Histórico (sin migración — canal cobertura)', color='tab:orange')

for esc, col in zip(esc_order, ['tab:red','tab:blue','tab:green']):
    c1 = cov_fut_con[cov_fut_con['Escenario']==esc]
    c0 = cov_fut_sin_cov[cov_fut_sin_cov['Escenario']==esc]
    plt.plot(c1['Año'], c1['Cobertura'], color=col, label=f'{esc.upper()} (con migración)')
    plt.plot(c0['Año'], c0['Cobertura'], color=col, linestyle='--', label=f'{esc.upper()} (sin migración — canal cobertura)')

plt.title('Tasa de cobertura: histórico y proyecciones por escenario (con/sin migración)')
plt.xlabel('Año'); plt.ylabel('Afiliados por pensionista'); plt.grid(True); plt.legend(ncol=2); plt.tight_layout(); plt.show()

# 6.3 IPD: histórico y proyecciones (dos contrafactuales)
# (A) principal: dependencia con M2 (con migración) y cobertura con/sin migración (canal cobertura)
ipd_list = []
for esc in esc_order:
    d = dep_fut[dep_fut['Escenario']==esc].merge(
        cov_fut_con[cov_fut_con['Escenario']==esc], on=['Año','Escenario'])
    d['IPD_con'] = d['Dep_frac_con_mig']/d['Cobertura']
    d2 = dep_fut[dep_fut['Escenario']==esc].merge(
        cov_fut_sin_cov[cov_fut_sin_cov['Escenario']==esc], on=['Año','Escenario'])
    d['IPD_sin_cov'] = d2['Dep_frac_con_mig']/d2['Cobertura']
    ipd_list.append(d[['Año','Escenario','IPD_con','IPD_sin_cov']])
ipd_fut = pd.concat(ipd_list, ignore_index=True)

# Histórico IPD (regla calibrada)
ipd_hist = dep_hist_frac / cov_hist
ipd_hist_sin_cov = dep_hist_frac / cov_hist_sin

plt.figure(figsize=(12,6))
plt.plot(df_reg['Año'], to_pct(ipd_hist), label='Histórico IPD (real)', color='tab:blue')
plt.plot(df_reg['Año'], to_pct(ipd_hist_sin_cov), '--', label='Histórico IPD (sin migración — canal cobertura)', color='tab:orange')

for esc, col in zip(esc_order, ['tab:red','tab:blue','tab:green']):
    g = ipd_fut[ipd_fut['Escenario']==esc]
    plt.plot(g['Año'], to_pct(g['IPD_con']), color=col, label=f'{esc.upper()} IPD (con migración)')
    plt.plot(g['Año'], to_pct(g['IPD_sin_cov']), color=col, linestyle='--', label=f'{esc.upper()} IPD (sin migración — canal cobertura)')

plt.title('Índice de Presión Demográfica (IPD): histórico y proyecciones por escenario')
plt.xlabel('Año'); plt.ylabel('IPD (dep/cov, en %)'); plt.grid(True); plt.legend(ncol=2); plt.tight_layout(); plt.show()

# ---------------- Configuración ----------------
# Coeficientes de la regla de cobertura (base del trabajo)
THETA_A = 0.85   # peso Población en Edad de Trabajar (PET) en afiliados
THETA_P = 0.90   # peso GE65 en pensionistas
GAMMA    = 0.25  # contribución del stock de extranjeros a afiliados

# Años-llave para la tabla
YEARS_PICK = [2025, 2035, 2050]

# (Opcional) Ruta de salida al Excel maestro. Si no quieres escribir, deja PATH_XLSX=None
PATH_XLSX = "/content/drive/MyDrive/TFM/Outputs/TFM_Tablas_Criticas.xlsx"

# ---------------- Comprobaciones mínimas ----------------
req_hist = ["Año", "Tasa_dependencia", "Población_mayores_65", "Stock_extranjeros"]
missing_hist = [c for c in req_hist if c not in df_reg.columns]
if missing_hist:
    raise KeyError(f"Faltan columnas en df_reg: {missing_hist}")

req_fut = ["Año", "Escenario", "Población_mayores_65", "Stock_extranjeros"]
missing_fut = [c for c in req_fut if c not in df_escenarios.columns]
if missing_fut:
    raise KeyError(f"Faltan columnas en df_escenarios: {missing_fut}")

# PET proyectada: si no existe, creamos una suave y conservadora por escenario
if "Población_edad_trabajar_proj" not in df_escenarios.columns:
    last_pet = float(df_reg.loc[df_reg["Año"] == df_reg["Año"].max(), "Población_edad_trabajar"].iloc[0])
    tasas_pet = {"pes": 0.999, "neu": 1.000, "opt": 1.002}  # puedes ajustar estas tasas si ya tienes otra proyección
    piezas = []
    for esc, g in tasas_pet.items():
        tmp = df_escenarios[df_escenarios["Escenario"] == esc].sort_values("Año").copy()
        años = tmp["Año"].to_numpy()
        serie = [last_pet * (g ** i) for i in range(1, len(años) + 1)]
        tmp["Población_edad_trabajar_proj"] = serie
        piezas.append(tmp)
    df_escenarios = pd.concat(piezas, ignore_index=True)

# ---------------- 1) Dependencia histórica (fracción) y modelo M2 ----------------
def to_frac(s):
    s = pd.Series(s, dtype="float64")
    return s/100.0 if s.mean() > 1 else s

dep_hist = to_frac(df_reg["Tasa_dependencia"])
exog_cols = ["Población_mayores_65", "Stock_extranjeros"]

m2 = SARIMAX(dep_hist,
             exog=df_reg[exog_cols],
             order=(1, 1, 0),
             enforce_stationarity=False, enforce_invertibility=False).fit(disp=False)

# ---------------- 2) Proyección de dependencia 2025–2050 (anclada a 2024) ----------------
ult_dep_2024 = float(dep_hist.iloc[-1])

fut_list = []
for esc in ["pes", "neu", "opt"]:
    g = df_escenarios[df_escenarios["Escenario"] == esc].sort_values("Año").copy()
    fc = m2.get_forecast(steps=len(g), exog=g[exog_cols]).predicted_mean
    # Anclaje: mantenemos el nivel de 2024 para el primer punto de 2025
    fc = fc - fc.iloc[0] + ult_dep_2024
    g["Dep_frac"] = fc.values
    fut_list.append(g[["Año", "Escenario", "Dep_frac", "Población_edad_trabajar_proj",
                       "Población_mayores_65", "Stock_extranjeros"]])
dep_fut = pd.concat(fut_list, ignore_index=True)

# ---------------- 3) Cobertura (con migración) y (sin migración) ----------------
def cobertura(pet, ge65, stock, theta_a=THETA_A, theta_p=THETA_P, gamma=GAMMA):
    afiliados = theta_a*pet + gamma*stock
    pensionistas = theta_p*ge65
    return afiliados / pensionistas

rows = []
for esc in ["pes", "neu", "opt"]:
    df_e = dep_fut[dep_fut["Escenario"] == esc].copy()
    df_e["Cov_con"] = cobertura(df_e["Población_edad_trabajar_proj"],
                                df_e["Población_mayores_65"],
                                df_e["Stock_extranjeros"],
                                THETA_A, THETA_P, GAMMA)
    df_e["Cov_sin"] = cobertura(df_e["Población_edad_trabajar_proj"],
                                df_e["Población_mayores_65"],
                                df_e["Stock_extranjeros"],
                                THETA_A, THETA_P, 0.0)  # << canal migración apagado
    df_e["IPD_con"] = df_e["Dep_frac"] / df_e["Cov_con"]
    df_e["IPD_sin"] = df_e["Dep_frac"] / df_e["Cov_sin"]

    # Filtramos años clave
    df_pick = df_e[df_e["Año"].isin(YEARS_PICK)].copy()
    for _, r in df_pick.iterrows():
        rows.append({
            "Escenario": esc,
            "Año": int(r["Año"]),
            "IPD con migración": float(r["IPD_con"]),
            "IPD sin migración": float(r["IPD_sin"]),
            "Diferencia (abs)": float(r["IPD_con"] - r["IPD_sin"]),
            "Diferencia (%)": float((r["IPD_con"]/r["IPD_sin"] - 1.0) * 100.0)
        })

df_contra = pd.DataFrame(rows).sort_values(["Escenario", "Año"]).reset_index(drop=True)

# Presentación amigable (opcional)
disp = df_contra.copy()
for c in ["IPD con migración", "IPD sin migración", "Diferencia (abs)"]:
    disp[c] = disp[c].map(lambda x: round(x, 6))
disp["Diferencia (%)"] = disp["Diferencia (%)"].map(lambda x: round(x, 6))
print("Tabla contrafactual (M2):")
display(disp)

