import os

def save_sheet_replace(path, df, sheet_name):
    """
    Crea el archivo si no existe. Si existe, reemplaza la hoja `sheet_name`
    conservando las demás, usando el motor openpyxl.
    """
    try:
        import openpyxl  # aseguramos motor disponible
    except Exception as e:
        raise RuntimeError("Falta openpyxl. Instálalo con: !pip install openpyxl") from e

    if os.path.exists(path):
        with pd.ExcelWriter(path, engine="openpyxl", mode="a", if_sheet_exists="replace") as w:
            df.to_excel(w, sheet_name=sheet_name, index=False)
    else:
        with pd.ExcelWriter(path, engine="openpyxl") as w:
            df.to_excel(w, sheet_name=sheet_name, index=False)

# Llamada
if PATH_XLSX:
    save_sheet_replace(PATH_XLSX, df_contra, "6_Contrafactual")
    print(f"[OK] Guardado '6_Contrafactual' -> {PATH_XLSX}")

