"""## Anexo D: Sensibilidad de Cobertura"""

# --- 0) Rutas
BASE_OUT = os.environ.get("TFM_OUT", "/content/drive/MyDrive/TFM/Outputs")
ANEX_DIR = os.path.join(BASE_OUT, "Anexos")
os.makedirs(ANEX_DIR, exist_ok=True)

# --- 1) Comprobaciones mínimas
req_hist = ["Año","Tasa_dependencia","Población_mayores_65","Población_edad_trabajar","Stock_extranjeros"]
faltan = [c for c in req_hist if c not in df_reg.columns]
if faltan:
    raise ValueError(f"Faltan columnas en df_reg: {faltan}. No puedo ejecutar Anexo D.")

req_fut = ["Año","Escenario","Población_mayores_65","Stock_extranjeros"]
faltan = [c for c in req_fut if c not in df_escenarios.columns]
if faltan:
    raise ValueError(f"Faltan columnas en df_escenarios: {faltan}. No puedo ejecutar Anexo D.")

# --- 2) Dependencia histórica en fracción y ARIMAX M2 (1,1,0)
def to_frac(s):
    s = pd.Series(s, dtype="float64")
    return s/100.0 if s.mean()>1 else s

dep_hist = to_frac(df_reg["Tasa_dependencia"])
exog_cols = ["Población_mayores_65","Stock_extranjeros"]
model_m2 = SARIMAX(dep_hist, exog=df_reg[exog_cols], order=(1,1,0),
                   enforce_stationarity=False, enforce_invertibility=False).fit(disp=False)

# --- 3) PET proyectada si no existe (suave, conservadora)
if "Población_edad_trabajar_proj" not in df_escenarios.columns:
    last_pet = float(df_reg.loc[df_reg["Año"]==df_reg["Año"].max(),"Población_edad_trabajar"].iloc[0])
    tasas_pet = {"pes":0.999, "neu":1.000, "opt":1.002}
    piezas = []
    for esc, g in tasas_pet.items():
        tmp = df_escenarios[df_escenarios["Escenario"]==esc].sort_values("Año").copy()
        años = tmp["Año"].to_numpy()
        serie = [last_pet*(g**i) for i in range(1, len(años)+1)]
        tmp["Población_edad_trabajar_proj"] = serie
        piezas.append(tmp)
    df_escenarios = pd.concat(piezas, ignore_index=True)

# --- 4) Proyección de dependencia 2025–2050 con anclaje 2024 (con migración)
ult_dep_2024 = float(dep_hist.iloc[-1])
preds = []
for esc in ["pes","neu","opt"]:
    tmp = df_escenarios[df_escenarios["Escenario"]==esc].copy()
    exog_fut = tmp[exog_cols]
    fc = model_m2.get_forecast(steps=len(tmp), exog=exog_fut).predicted_mean
    # anclar a 2024 (con migración)
    fc = fc - fc.iloc[0] + ult_dep_2024
    tmp["Dep_frac"] = fc.values
    preds.append(tmp[["Año","Escenario","Dep_frac"]])
dep_fut = pd.concat(preds, ignore_index=True)

# --- 5) Función cobertura e IPD para una terna (θa, θp, γ)
def cobertura_IPD2050(theta_a, theta_p, gamma):
    out = []
    for esc in ["pes","neu","opt"]:
        fut = df_escenarios[df_escenarios["Escenario"]==esc].copy()
        dep = dep_fut[dep_fut["Escenario"]==esc].set_index("Año")["Dep_frac"]

        pet = fut["Población_edad_trabajar_proj"]
        stock = fut["Stock_extranjeros"]
        ge65 = fut["Población_mayores_65"]
        afiliados = theta_a*pet + gamma*stock
        pensionistas = theta_p*ge65
        cobertura = afiliados / pensionistas

        df_tmp = pd.DataFrame({"Año": fut["Año"],
                               "Escenario": esc,
                               "Dep": dep.values,
                               "Cob": cobertura.values})
        df_2050 = df_tmp.loc[df_tmp["Año"]==2050]
        ipd_2050 = float(df_2050["Dep"] / df_2050["Cob"])
        out.append((esc, ipd_2050))
    return dict(out)

# --- 6) Barrido de sensibilidades
base = dict(theta_a=0.85, theta_p=0.90, gamma=0.25)
mults = [0.8, 0.9, 1.0, 1.1, 1.2]

resultados = []

# Base
res = cobertura_IPD2050(**base)
res["combo"] = "base"
resultados.append(res)

# Uno-a-uno ±10% y ±20%
for par, key in [("θa","theta_a"),("θp","theta_p"),("γ","gamma")]:
    for m in [0.8, 0.9, 1.1, 1.2]:
        params = base.copy(); params[key] = base[key]*m
        r = cobertura_IPD2050(**params); r["combo"] = f"{par}×{m:.1f}"
        resultados.append(r)

# Conjuntas (casos extremos)
for tag, m in [("all_low", 0.8), ("all_high", 1.2)]:
    params = {k: v*m for k,v in base.items()}
    r = cobertura_IPD2050(**params); r["combo"] = tag
    resultados.append(r)

df_sens = pd.DataFrame(resultados).set_index("combo")
# Orden columnas por escenario
df_sens = df_sens[["pes","neu","opt"]]

# --- 7) Min/Max por escenario y exportación
resumen = pd.DataFrame({
    "Escenario": ["pes","neu","opt"],
    "IPD2050_base": [df_sens.loc["base","pes"], df_sens.loc["base","neu"], df_sens.loc["base","opt"]],
    "IPD2050_min":  [df_sens["pes"].min(), df_sens["neu"].min(), df_sens["opt"].min()],
    "IPD2050_max":  [df_sens["pes"].max(), df_sens["neu"].max(), df_sens["opt"].max()],
})
xlsx_path = os.path.join(ANEX_DIR, "Anexo_D_sensibilidad.xlsx")
with pd.ExcelWriter(xlsx_path) as xw:
    df_sens.to_excel(xw, sheet_name="IPD2050_por_combo")
    resumen.to_excel(xw, sheet_name="Resumen_min_max", index=False)
print(f"[OK] Anexo D -> {xlsx_path}")

# --- 8) Gráfico de barras Base vs Min/Max por escenario
