plt.xticks(x, resumen["Escenario"])
plt.ylabel("IPD 2050 (dep/cov)")
plt.title("Sensibilidad IPD 2050 a parámetros de cobertura (±10–20%)")
plt.grid(axis="y", alpha=0.3)
plt.legend(ncol=3)
